#define main fresh_training_main
#include "fresh_noffn.cu"
#undef main
#include "noffn_cpu.hpp"
int main(int argc,char** argv){try{if(argc!=2)throw std::runtime_error("checkpoint required");Config c;c.layers=2;c.d=64;c.s=16;c.m=64;c.e=128;c.vocab=261;CpuModel init(c);SortedGpuTrainer t(init);t.spec.erase(std::remove_if(t.spec.begin(),t.spec.end(),[](const TensorSpec& s){return s.name.find(".ff.")!=std::string::npos;}),t.spec.end());for(auto it=t.graph.w.begin();it!=t.graph.w.end();){if(it->first.find(".ff.")!=std::string::npos){auto k=it->first;t.master.erase(k);t.moment.erase(k);t.variance.erase(k);t.scales.erase(k);it=t.graph.w.erase(it);}else ++it;}std::ifstream in(argv[1],std::ios::binary);if(!in)throw std::runtime_error("open");for(auto* map:{&t.master,&t.moment,&t.variance})for(auto& kv:*map){Vec v(kv.second->n);in.read((char*)v.data(),v.size()*4);if(!in)throw std::runtime_error("length");check(cudaMemcpy(kv.second->p,v.data(),v.size()*4,cudaMemcpyHostToDevice));}if(in.peek()!=EOF)throw std::runtime_error("trailing");t.project();for(int transform=0;transform<7;transform++){int n=0,correct=0;double loss=0;for(int a=0;a<8;a++){int b=(a+7)%8;for(int q=0;q<2;q++){auto y=example(t,false,a,b,q,transform);auto v=y->value.host();int target=20+(q?b:a);float mx=*std::max_element(v.begin(),v.end());double sum=0;for(float z:v)sum+=std::exp(z-mx);loss+=std::log(sum)+mx-v[target];correct+=int(std::max_element(v.begin(),v.end())-v.begin())==target;n++;}}printf("TEST transform=%d correct=%d n=%d nll=%.6f\n",transform,correct,n,loss/n);}reset(t);tao::noffn::CpuModel cpu(c);for(auto& kv:cpu.w)kv.second=t.graph.w.at(kv.first)->value.host();auto state=cpu.initial();double worst=0;int same=0;unsigned token=10;for(int i=0;i<24;i++){auto a=cpu.step(token,state);auto b=forward(t.graph,token,false)->value.host();for(size_t j=0;j<a.size();j++)worst=std::max(worst,double(std::abs(a[j]-b[j])));int ca=std::max_element(a.begin(),a.end())-a.begin(),cb=std::max_element(b.begin(),b.end())-b.begin();same+=ca==cb;token=i<7?20+i:ca;t.detach();}printf("PARITY greedy=%d/24 max_abs=%.9g\n",same,worst);if(same!=24||worst>1e-3)throw std::runtime_error("parity");return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
